#!/usr/bin/env python3
import argparse
import collections
import os
import subprocess
import sys
import fs_cmds


def log_filter(data):
    errors, warnings, infos = [], [], 0
    for line in data.splitlines():
        low = line.lower()
        if any(s in low for s in ('error', 'fatal')):
            errors.append(line)
        elif any(s in low for s in ('warn', 'deprecated')):
            warnings.append(line)
        elif 'info' in low:
            infos += 1
    ec, wc = collections.Counter(errors), collections.Counter(warnings)
    out = ['Log Summary', f'   [error] {len(errors)} errors ({len(ec)} unique)',
           f'   [warn] {len(warnings)} warnings ({len(wc)} unique)',
           f'   [info] {infos} info messages', '']
    if errors:
        out.append('[ERRORS]')
        for line, n in ec.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    if warnings:
        out.append('[WARNINGS]')
        for line, n in wc.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    return '\n'.join(out).rstrip() + '\n'


def main():
    args = sys.argv[1:]
    if args and args[0] in ('ls', 'tree', 'smart'):
        command, rest = args[0], args[1:]
        if any(x in ('-h', '--help') for x in rest):
            help_text = {
                'ls': 'List directory contents with token-optimized output\n\nUsage: executable ls [OPTIONS] [ARGS...]',
                'tree': 'Directory tree with token-optimized output\n\nUsage: executable tree [OPTIONS] [ARGS...]',
                'smart': 'Generate 2-line technical summary (heuristic-based)\n\nUsage: executable smart [OPTIONS] <FILE>',
            }[command]
            print(help_text)
            return 0
        return getattr(fs_cmds, command)(rest)
    if args and args[0] == 'log':
        parser = argparse.ArgumentParser(prog='executable log', add_help=True)
        parser.add_argument('file', nargs='?')
        parser.add_argument('-v', action='count', default=0)
        parser.add_argument('--ultra-compact', action='store_true')
        ns = parser.parse_args(args[1:])
        try:
            data = open(ns.file, encoding='utf-8', errors='replace').read() if ns.file else sys.stdin.read()
        except OSError as e:
            print(f'rtk: {e.strerror} (os error {e.errno})', file=sys.stderr)
            return 1
        sys.stdout.write(log_filter(data))
        return 0
    if args and args[0] == 'summary':
        cmd = args[1:]
        if not cmd or cmd == ['--help']:
            print('Run command and show heuristic summary\n\nUsage: executable summary [OPTIONS] [COMMAND]...\n\nArguments:\n  [COMMAND]...  Command to run and summarize\n\nOptions:\n  -v, --verbose...     Verbosity level (-v, -vv, -vvv)\n      --ultra-compact  Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env       Set SKIP_ENV_VALIDATION=1 for child processes\n  -h, --help           Print help')
            return 0
        for flag in ('-v', '--ultra-compact', '--skip-env'):
            if flag in cmd:
                cmd.remove(flag)
        p = subprocess.run(' '.join(cmd), shell=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        lines = p.stdout.splitlines()
        label = '[ok]' if p.returncode == 0 else '[FAIL]'
        print(f"{label} Command: {' '.join(cmd)}")
        print(f'   {max(1, len(lines))} lines of output')
        errs = [x for x in lines if any(w in x.lower() for w in ('error', 'fatal', 'panic', 'exception'))]
        warns = [x for x in lines if 'warn' in x.lower() or 'deprecated' in x.lower()]
        if errs or warns:
            print('\nLog Summary:')
            print(f'   [error] {len(errs)} errors')
            print(f'   [warn] {len(warns)} warnings')
            print('   [info] 0 info')
        else:
            vals = [x.strip() for x in lines if x.strip()]
            print(f'\nList ({len(vals)} items):')
            for x in vals[:10]: print('   • ' + x[:120])
        return 0
    if args and args[0] in ('-V', '--version'):
        print('rtk 0.42.0')
        return 0
    print('Usage: executable <COMMAND>', file=sys.stderr)
    return 2


if __name__ == '__main__':
    raise SystemExit(main())
"}

