            keys = sorted(v, key=lambda x: str(x))
            for i, key in enumerate(keys):
                item = v[key]
                kp = " " * (indent + 2)
                k = str(key)
                if isinstance(item, (dict, list)):
                    lines.append(f"{kp}{k}:")
                    lines.append(value(item, level + 1, indent + 2))
                else:
                    lines.append(f"{kp}{k}: {scalar(item)}" + ("," if keys_only and i + 1 < len(keys) else ""))
            lines.append(pad + "}")
            return "\n".join(lines)
        if isinstance(v, list):
            if level > depth:
                return pad + "..."
            if not v:
                return pad + "[]"
            if keys_only:
                primitive = all(not isinstance(x, (dict, list)) for x in v)
                if primitive and len(v) > 1:
                    return f"{pad}[{_kind(v[0])}] ({len(v)})"
                if not primitive and len(v) > 1:
                    shaped = value(v[0], level + 1, indent + 2).splitlines()
